class Base {
    Base() {
        System.out.println(this); // calls the overridden toString()
    }
}

class Sub extends Base {
    private final String name;

    Sub(String name) {
        super();
        // name is still null, while Base() runs
        this.name = name;
    }

    @Override
    public String toString() {
        return name.toUpperCase();
    }
}

