import java.util.Objects;

class Base { }

class Sub extends Base {
    private final String name;
    private final String upper;

    Sub(String name) {
        super();
        this.name = Objects.requireNonNull(name);
        this.upper = name.toUpperCase();
    }
}

class Base {
    String inheritedMethod() {
        return "";
    }
}

class Sub extends Base {
    private String a;
    private String b;
    private Runnable c;
    private Object d;

    Sub(String s) {
        super();
        this.a = compute(s); // instance method
    }

    Sub(int i) {
        super();
        this.b = this.toString(); // explicit this
    }

    Sub(long l) {
        super();
        this.c = () -> compute("x"); // lambda calling an instance method
    }

    Sub(short s) {
        super();
        this.d = new Object() { }; // anonymous class
    }

    Sub(byte b) {
        super();
        this.a = inheritedMethod(); // inherited instance method
    }

    String compute(String s) {
        return s;
    }
}

