class Base {
    protected int inherited;
}

class Sub extends Base {
    private static int counter;
    private int withInitializer = 0;
    private int other;

    Sub(int x) {
        super();
        withInitializer = x; // has an initializer
    }

    Sub(long x) {
        super();
        counter = (int) x; // static field
    }

    Sub(short x) {
        super();
        inherited = x; // inherited field
    }

    Sub(byte x) {
        super();
        other += x; // compound assignment
    }
}

